function dt = dt_instrument_smimport(smimport_model_file, output_model_file, chain, compiled_model, opts)
% DT_INSTRUMENT_SMIMPORT  Instruments an smimport model with EE frame and sensors.
%
% Takes a raw Simscape model generated by smimport from URDF, adapts it into
% the Digital Twin (dt) interface, and applies:
%   1. dt_add_ee_frame(dt, chain, struct('model', compiled_model, ...))
%   2. dt_add_sensors(dt, struct(...))
%
% This generates the 3rd model variant:
%   Model 1: Multibody twin generated via DH parameters (dt_<robot>_dh.slx)
%   Model 2: Native raw Simscape import from URDF (dt_<robot>_smimport.slx)
%   Model 3: Native Simscape import + EE frame + Sensors (dt_<robot>_smimport_sensed.slx)
%
% =========================================================================
% INPUTS:
%   smimport_model_file (char)   Path or name of the raw smimport .slx model.
%   output_model_file   (char)   [optional] Path or name for the instrumented model.
%                                Default: [smimport_stem, '_sensed.slx'].
%   chain               (struct) Active kinematic chain from urdf_build_chain.
%   compiled_model      (struct) CasADi compiled model struct from casadi_compile.
%   opts                (struct) [optional] Options:
%                                  .verbose    (logical, default: false)
%                                  .save_model (logical, default: true)
%
% OUTPUT:
%   dt                  (struct) Instrumented Digital Twin model structure.
% =========================================================================

    if nargin < 5 || isempty(opts)
        opts = struct();
    end
    verbose    = isfield(opts, 'verbose') && opts.verbose;
    save_model = ~isfield(opts, 'save_model') || opts.save_model;

    % Resolve source model name and path
    [src_dir, src_stem, src_ext] = fileparts(smimport_model_file);
    if isempty(src_ext), src_ext = '.slx'; end
    if isempty(src_dir), src_dir = pwd; end
    src_full = fullfile(src_dir, [src_stem, src_ext]);
    assert(exist(src_full, 'file') == 2 || exist(src_full, 'file') == 4, ...
           'dt_instrument_smimport:SourceNotFound', 'Source smimport model not found: %s', src_full);

    % Resolve destination model name and path
    if nargin < 2 || isempty(output_model_file)
        dst_stem = [src_stem, '_sensed'];
        dst_dir  = src_dir;
        dst_full = fullfile(dst_dir, [dst_stem, '.slx']);
    else
        [dst_dir, dst_stem, dst_ext] = fileparts(output_model_file);
        if isempty(dst_ext), dst_ext = '.slx'; end
        if isempty(dst_dir), dst_dir = src_dir; end
        dst_full = fullfile(dst_dir, [dst_stem, dst_ext]);
    end

    if verbose
        fprintf('\n[dt_instrument_smimport] Instrumenting smimport model:\n');
        fprintf('  Source Model : %s\n', src_full);
        fprintf('  Target Model : %s\n', dst_full);
    end

    % Close destination model if currently open
    if bdIsLoaded(dst_stem)
        close_system(dst_stem, 0);
    end

    % Load source model if not already open
    if ~bdIsLoaded(src_stem)
        load_system(src_full);
    end

    % Clone source model to destination
    save_system(src_stem, dst_full);
    if ~strcmp(src_stem, dst_stem)
        close_system(src_stem, 0);
        load_system(dst_full);
    end

    % -----------------------------------------------------------------------
    % 1. Adapt smimport Model into dt Interface
    % -----------------------------------------------------------------------
    dt = struct();
    dt.model_name = dst_stem;
    dt.model_file = dst_full;
    dt.n_dof      = chain.n;

    % World reference frame port
    p_world = get_param([dst_stem, '/World'], 'PortHandles');
    assert(~isempty(p_world.RConn), 'dt_instrument_smimport:WorldPortNotFound', ...
           'World block does not have valid RConn frame port.');
    dt.world_port = p_world.RConn(1);

    % Terminal link follower frame port
    term_link_block = [dst_stem, '/', chain.active_links{end}];
    assert(exist_block(term_link_block), 'dt_instrument_smimport:TerminalLinkNotFound', ...
           'Terminal link block not found: %s', term_link_block);
    p_term = get_param(term_link_block, 'PortHandles');
    if ~isempty(p_term.RConn)
        dt.last_port = p_term.RConn(1);
    else
        dt.last_port = p_term.LConn(1);
    end

    % Active joint block paths
    dt.joint_blocks = cell(chain.n, 1);
    for i = 1:chain.n
        jt_path = [dst_stem, '/', chain.active_joints{i}.name];
        assert(exist_block(jt_path), 'dt_instrument_smimport:JointNotFound', ...
               'Active joint block not found in smimport model: %s', jt_path);
        dt.joint_blocks{i} = jt_path;
    end

    % Compute graphical layout bounding box
    blks = find_system(dst_stem, 'SearchDepth', 1);
    max_x = 0; sum_y = 0; count_blks = 0;
    for i = 2:length(blks)
        pos = get_param(blks{i}, 'Position');
        if pos(3) > max_x, max_x = pos(3); end
        sum_y = sum_y + (pos(2) + pos(4)) / 2;
        count_blks = count_blks + 1;
    end
    dt.x_col_end = max_x + 120;
    dt.y_main    = sum_y / max(1, count_blks);

    % -----------------------------------------------------------------------
    % 2. Add End-Effector Reference Frame (dt_add_ee_frame)
    % -----------------------------------------------------------------------
    opts_ee = struct();
    opts_ee.model      = compiled_model;
    opts_ee.verbose    = verbose;
    opts_ee.save_model = true;
    dt = dt_add_ee_frame(dt, chain, opts_ee);

    % -----------------------------------------------------------------------
    % 3. Add Sensors (dt_add_sensors)
    % -----------------------------------------------------------------------
    opts_sens = struct();
    opts_sens.verbose    = verbose;
    opts_sens.save_model = save_model;
    dt = dt_add_sensors(dt, opts_sens);

    % -----------------------------------------------------------------------
    % 4. Add Trajectory Excitation (dt_add_trajectory)
    % -----------------------------------------------------------------------
    if (isfield(opts, 'traj') && ~isempty(opts.traj)) || (isfield(opts, 'add_trajectory') && opts.add_trajectory)
        opts_traj = struct('verbose', verbose, 'save_model', save_model);
        if isfield(opts, 'joint_signs') && ~isempty(opts.joint_signs)
            opts_traj.joint_signs = opts.joint_signs;
        else
            opts_traj.joint_signs = ones(chain.n, 1);
        end
        if isfield(opts, 'traj') && ~isempty(opts.traj)
            dt = dt_add_trajectory(dt, opts.traj, opts_traj);
        else
            dt = dt_add_trajectory(dt, [], opts_traj);
        end
    end

    if verbose
        fprintf('  [COMPLETE] Successfully instrumented smimport model with EE frame, sensors, and trajectory!\n');
    end

end

% =========================================================================
% LOCAL HELPER
% =========================================================================
function tf = exist_block(blk_path)
    try
        get_param(blk_path, 'Handle');
        tf = true;
    catch
        tf = false;
    end
end
